<script setup lang="ts">
import{computed,onMounted,onBeforeUnmount,ref}from'vue';import{open as openDialog}from'@tauri-apps/plugin-dialog';import{getCurrentWebview}from'@tauri-apps/api/webview';import{Plus,Search,Settings,Image,Video,Music,Files,Trash2,LayoutDashboard,Library,PanelLeftClose,PanelLeftOpen,X,Play,FileText}from'lucide-vue-next';import HomeView from'./components/HomeView.vue';import CanvasView from'./components/CanvasView.vue';import SearchPalette from'./components/SearchPalette.vue';import InspectorPanel from'./components/InspectorPanel.vue';import{backend}from'./services/backend';import{useWorkspace}from'./stores/workspace';import type{Asset,CanvasNode,SearchResult}from'./types';
type Preferences={theme:'system'|'light'|'dark';gridSize:number;confirmDelete:boolean};const defaultPreferences:Preferences={theme:'system',gridSize:24,confirmDelete:true};function loadPreferences():Preferences{try{return{...defaultPreferences,...JSON.parse(localStorage.getItem('infinite-canvas-preferences')||'{}')}}catch{return{...defaultPreferences}}}
const ws=useWorkspace(),searchOpen=ref(false),settingsOpen=ref(false),leftOpen=ref(true),view=ref<'canvas'|'assets'|'trash'>('canvas'),error=ref(''),previewAsset=ref<Asset>(),preferences=ref<Preferences>(loadPreferences());const isTauri=!!(window as any).__TAURI_INTERNALS__;const appTheme=computed(()=>preferences.value.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):preferences.value.theme);function applyPreferences(){document.documentElement.dataset.theme=appTheme.value;document.documentElement.style.setProperty('--canvas-grid-size',preferences.value.gridSize+'px')}function savePreferences(){localStorage.setItem('infinite-canvas-preferences',JSON.stringify(preferences.value));applyPreferences()}function resetPreferences(){preferences.value={...defaultPreferences};savePreferences()}
function openSettings(){settingsOpen.value=true;const shade=document.createElement('div');shade.className='settings-shade';shade.innerHTML=`<section class="settings-dialog"><header><div><h2>设置</h2><p>自定义 Infinite Canvas 的外观与操作。</p></div><button class="settings-close" aria-label="关闭">×</button></header><div class="settings-row"><div><b>外观</b><small>选择应用使用的颜色主题</small></div><select class="settings-theme"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></div><div class="settings-row"><div><b>画布网格</b><small>调整网格点之间的距离</small></div><div class="settings-range"><input class="settings-grid" type="range" min="12" max="48" step="4"><output></output></div></div><label class="settings-row settings-check"><div><b>删除前确认</b><small>删除画布前显示确认提示</small></div><input class="settings-confirm" type="checkbox"></label><footer><button class="settings-reset">恢复默认设置</button><button class="primary settings-done">完成</button></footer></section>`;document.body.appendChild(shade);const theme=shade.querySelector<HTMLSelectElement>('.settings-theme')!,grid=shade.querySelector<HTMLInputElement>('.settings-grid')!,output=shade.querySelector<HTMLOutputElement>('output')!,confirmDelete=shade.querySelector<HTMLInputElement>('.settings-confirm')!;theme.value=preferences.value.theme;grid.value=String(preferences.value.gridSize);output.value=preferences.value.gridSize+' px';confirmDelete.checked=preferences.value.confirmDelete;const close=()=>{settingsOpen.value=false;shade.remove()};theme.onchange=()=>{preferences.value.theme=theme.value as Preferences['theme'];savePreferences()};grid.oninput=()=>{preferences.value.gridSize=Number(grid.value);output.value=grid.value+' px';savePreferences()};confirmDelete.onchange=()=>{preferences.value.confirmDelete=confirmDelete.checked;savePreferences()};shade.querySelector<HTMLElement>('.settings-reset')!.onclick=()=>{resetPreferences();theme.value=preferences.value.theme;grid.value=String(preferences.value.gridSize);output.value=grid.value+' px';confirmDelete.checked=preferences.value.confirmDelete};shade.querySelector<HTMLElement>('.settings-close')!.onclick=close;shade.querySelector<HTMLElement>('.settings-done')!.onclick=close;shade.onclick=e=>{if(e.target===shade)close()}}
const selectedNode=computed(()=>ws.nodes.find(n=>ws.selected.has(n.id)));const activeCanvases=computed(()=>ws.data?.canvases.filter(c=>!c.deleted_at)||[]);const trash=computed(()=>({canvases:ws.data?.canvases.filter(c=>c.deleted_at)||[],nodes:ws.data?.nodes.filter(n=>n.deleted_at)||[],assets:ws.data?.assets.filter(a=>a.deleted_at)||[]}));
async function create(name:string,path:string){try{if(!path&&isTauri)path=(await openDialog({directory:true,title:'选择工作区保存位置'})as string)||'';if(!path)path='browser://local';ws.setData(await backend.createWorkspace(path,name))}catch(e){error.value=String(e)}}
async function openWs(path:string){try{if(!path&&isTauri)path=(await openDialog({directory:true,title:'打开工作区'})as string)||'';if(path)ws.setData(await backend.openWorkspace(path))}catch(e){error.value=String(e)}}
async function addCanvas(){if(!ws.data)return;const c=await backend.createCanvas(`画布 ${activeCanvases.value.length+1}`);ws.data.canvases.push(c);ws.activeCanvasId=c.id;view.value='canvas'}
async function importFiles(){if(!isTauri)return error.value='请在桌面版中导入文件';const picked=await openDialog({multiple:true,directory:false});if(!picked)return;await importPaths(Array.isArray(picked)?picked:[picked])}
async function importPaths(paths:string[],x=100,y=100){try{const out=await backend.importFiles(paths);if(!ws.data)return;for(const [i,r] of out.entries()){if(!ws.data.assets.some(a=>a.id===r.asset.id))ws.data.assets.push(r.asset);const supported=['image','video','audio','pdf','markdown','code'];const type=supported.includes(r.asset.type)?r.asset.type:'file';const text=['markdown','code'].includes(type)?await backend.assetText(r.asset.id):'';await ws.createNode({asset_id:r.asset.id,type:type as any,title:r.asset.original_name,x:x+(i%4)*330,y:y+Math.floor(i/4)*250,width:type==='image'||type==='video'?300:type==='pdf'||type==='markdown'||type==='code'?360:280,height:type==='image'||type==='video'?210:type==='pdf'||type==='markdown'||type==='code'?260:150,content_json:JSON.stringify({url:backend.assetUrl(r.asset),mimeType:r.asset.mime_type,text,language:r.asset.extension})})}}catch(e){error.value=String(e)}}
function drop(e:DragEvent){e.preventDefault();const paths=Array.from(e.dataTransfer?.files||[]).map((f:any)=>f.path).filter(Boolean);if(paths.length)importPaths(paths)}
async function deleteCanvas(id:string){if(!ws.data||(preferences.value.confirmDelete&&!confirm('将此画布移入回收站？')))return;await backend.trashCanvas(id);const canvas=ws.data.canvases.find(c=>c.id===id);if(canvas)canvas.deleted_at=Date.now();if(ws.activeCanvasId===id)ws.activeCanvasId=activeCanvases.value[0]?.id||''}
async function paste(e:ClipboardEvent){if(!ws.data)return;const text=e.clipboardData?.getData('text/plain')||'';if(/^https?:\/\//i.test(text)){await ws.createNode({type:'link',title:new URL(text).hostname,content_json:JSON.stringify({url:text}),x:100,y:100,width:300,height:180})}else if(text&&!['INPUT','TEXTAREA'].includes((e.target as HTMLElement).tagName)){await ws.createNode({type:'text',title:text.slice(0,40),content_json:JSON.stringify({html:text.replace(/</g,'&lt;')}),x:100,y:100})}const file=e.clipboardData?.files?.[0] as any;if(file?.path)importPaths([file.path])}
function pick(r:SearchResult){searchOpen.value=false;if(r.kind==='canvas')ws.activeCanvasId=r.id;else if(r.canvas_id){ws.activeCanvasId=r.canvas_id;ws.selected=new Set([r.id])}view.value='canvas'}
function key(e:KeyboardEvent){if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();searchOpen.value=true}}function settingsClick(e:MouseEvent){const button=(e.target as HTMLElement).closest('.topbar .icon:last-child');if(button)openSettings()}function updateNode(n:CanvasNode){if(!ws.data)return;const i=ws.data.nodes.findIndex(x=>x.id===n.id);ws.data.nodes[i]=n;ws.saveNodes([n])}
async function restore(kind:string,id:string){await backend.restoreItems(kind,[id]);const row:any=(ws.data as any)[kind==='canvas'?'canvases':kind==='node'?'nodes':'assets'].find((x:any)=>x.id===id);row.deleted_at=null}
let unlistenDrop:(()=>void)|undefined;onMounted(async()=>{applyPreferences();window.addEventListener('keydown',key);window.addEventListener('paste',paste);window.addEventListener('click',settingsClick);window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',drop);if(isTauri)unlistenDrop=await getCurrentWebview().onDragDropEvent(e=>{if(e.payload.type==='drop'&&e.payload.paths.length)importPaths(e.payload.paths,e.payload.position.x,e.payload.position.y)})});onBeforeUnmount(()=>{backend.markClean();unlistenDrop?.();window.removeEventListener('keydown',key);window.removeEventListener('paste',paste);window.removeEventListener('click',settingsClick);window.removeEventListener('drop',drop)});
</script>
<template><HomeView v-if="!ws.data" @create="create" @open="openWs"/><div v-else class="app-shell"><header class="topbar"><button class="icon" @click="leftOpen=!leftOpen"><PanelLeftClose v-if="leftOpen"/><PanelLeftOpen v-else/></button><b>{{ws.data.workspace.name}}</b><span>/</span><input v-if="ws.activeCanvas" v-model="ws.activeCanvas.name" @change="backend.updateCanvas(ws.activeCanvas)"><i/><button @click="searchOpen=true"><Search/>搜索 <kbd>Ctrl K</kbd></button><button class="icon"><Settings/></button></header>
 <aside v-if="leftOpen" class="sidebar"><div class="section-title">画布<button @click="addCanvas"><Plus/></button></div><div v-for="c in activeCanvases" :key="c.id" class="canvas-row" :class="{active:view==='canvas'&&ws.activeCanvasId===c.id}"><button @click="ws.activeCanvasId=c.id;view='canvas'"><LayoutDashboard/>{{c.name}}</button><button class="canvas-delete" title="删除画布" @click.stop="deleteCanvas(c.id)"><X/></button></div><div class="section-title">素材</div><button @click="view='assets';ws.assetFilter='all'"><Library/>全部素材 <span>{{ws.assets.length}}</span></button><button @click="view='assets';ws.assetFilter='image'"><Image/>图片</button><button @click="view='assets';ws.assetFilter='video'"><Video/>视频</button><button @click="view='assets';ws.assetFilter='audio'"><Music/>音频</button><button @click="view='assets';ws.assetFilter='file'"><Files/>文件</button><div class="sidebar-spacer"/><button @click="view='trash'"><Trash2/>回收站</button></aside>
 <main class="content"><CanvasView v-if="view==='canvas'&&ws.activeCanvas"/><section v-else-if="view==='assets'" class="library"><header><div><h2>素材库</h2><p>所有文件均托管在工作区内</p></div><button class="primary" @click="importFiles"><Plus/>导入文件</button></header><div class="asset-grid"><article v-for="a in ws.assets.filter(x=>ws.assetFilter==='all'||x.type===ws.assetFilter)" :key="a.id" :class="'asset-'+a.type" @click="previewAsset=a"><div class="asset-thumb"><img v-if="a.type==='image'" :src="backend.assetUrl(a)" :alt="a.original_name"><div v-else-if="a.type==='video'" class="video-card-visual"><Video/><span><Play/>预览视频</span></div><div v-else-if="a.type==='audio'" class="audio-card-visual"><Music/><div class="waveform"><i v-for="n in 22" :key="n" :style="{height:(8+(n*13)%34)+'px'}"/></div></div><div v-else class="file-card-visual"><FileText/><strong>{{a.extension.toUpperCase()||'FILE'}}</strong></div><span class="asset-kind">{{a.extension.toUpperCase()||a.type}}</span></div><div class="asset-meta"><b :title="a.original_name">{{a.original_name}}</b><small>{{(a.size/1024/1024).toFixed(1)}} MB · 使用 {{a.usage_count||0}} 次</small></div></article></div></section><section v-else class="library"><header><div><h2>回收站</h2><p>删除的内容可以恢复，资源不会被立即清除</p></div></header><div class="trash-list"><template v-for="kind in ['canvases','nodes','assets']" :key="kind"><h3>{{kind}}</h3><div v-for="item in trash[kind as keyof typeof trash]" :key="item.id"><span>{{(item as any).name||(item as any).title||(item as any).original_name}}</span><button @click="restore(kind.slice(0,-1),(item as any).id)">恢复</button></div></template></div></section></main>
 <InspectorPanel v-if="view==='canvas'" :node="selectedNode" @change="updateNode"/><SearchPalette :open="searchOpen" @close="searchOpen=false" @pick="pick"/><div v-if="previewAsset" class="media-lightbox" @click.self="previewAsset=undefined"><header><div><b>{{previewAsset.original_name}}</b><small>{{previewAsset.extension.toUpperCase()}} · {{(previewAsset.size/1024/1024).toFixed(1)}} MB</small></div><button @click="previewAsset=undefined"><X/></button></header><img v-if="previewAsset.type==='image'" :src="backend.assetUrl(previewAsset)" :alt="previewAsset.original_name"><video v-else-if="previewAsset.type==='video'" :src="backend.assetUrl(previewAsset)" controls autoplay/><audio v-else-if="previewAsset.type==='audio'" :src="backend.assetUrl(previewAsset)" controls autoplay/><div v-else class="file-preview"><FileText/><b>{{previewAsset.original_name}}</b><button class="primary" @click="backend.openAsset(previewAsset!.id)">使用系统程序打开</button></div></div><div v-if="error" class="toast" @click="error=''">{{error}}</div><button v-if="view==='canvas'" class="import-fab" @click="importFiles"><Plus/>导入</button></div></template>
